"use client";

import { useId, useState, type CSSProperties } from "react";
import "./styles/skeuo-progress-rings.css";

export type ProgressRing = {
  id: string;
  label: string;
  value: number;
  max: number;
  unit?: string;
  color?: string;
};

const formatter = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });

export function SkeuoProgressRings({
  items,
  title = "Daily goals",
  animate = true,
}: {
  items: ProgressRing[];
  title?: string;
  animate?: boolean;
}) {
  const id = useId();
  const [selectedId, setSelectedId] = useState(items[0]?.id);
  const rings = items.map((item) => {
    const value = Number.isFinite(item.value) ? item.value : 0;
    const max = Number.isFinite(item.max) && item.max > 0 ? item.max : 0;
    const percent = max ? Math.min(100, Math.max(0, value / max * 100)) : 0;
    return { ...item, value, max, percent };
  });
  const selected = rings.find((ring) => ring.id === selectedId) ?? rings[0];
  if (!selected) return null;

  const spacing = Math.min(23, 56 / Math.max(1, rings.length - 1));
  const thickness = Math.min(14, spacing * 0.65);

  return (
    <section data-sk-root="" className="sk-progress-rings" aria-labelledby={`${id}-title`}>
      <h2 id={`${id}-title`}>{title}</h2>
      <div className="sk-rings-layout">
        <div className="sk-rings-dial" data-animate={animate || undefined}>
          <svg viewBox="0 0 240 240" aria-hidden="true">
            <defs>
              <linearGradient id={`${id}-groove`} x2="0%" y2="100%">
                <stop stopColor="var(--sk-groove-wall)" />
                <stop offset=".55" stopColor="var(--sk-base)" />
                <stop offset="1" stopColor="var(--sk-well)" />
              </linearGradient>
              <linearGradient id={`${id}-floor`} x2="0%" y2="100%">
                <stop stopColor="var(--sk-base)" />
                <stop offset="1" stopColor="var(--sk-well)" />
              </linearGradient>
              <linearGradient id={`${id}-bevel`}>
                <stop stopColor="black" stopOpacity=".42" />
                <stop offset=".52" stopColor="black" stopOpacity=".22" />
                <stop offset="1" stopColor="white" stopOpacity=".24" />
              </linearGradient>
              <linearGradient id={`${id}-fill`}>
                <stop stopColor="black" stopOpacity=".16" />
                <stop offset=".48" stopColor="white" stopOpacity=".05" />
                <stop offset=".83" stopColor="white" stopOpacity=".32" />
                <stop offset="1" stopColor="white" stopOpacity=".44" />
              </linearGradient>
            </defs>
            {rings.map((ring, index) => {
              const radius = 104 - index * spacing;
              const style = {
                "--sk-ring-color": ring.color,
                "--sk-ring-progress": ring.percent,
                "--sk-ring-delay": `${Math.min(index, 5) * 85}ms`,
              } as CSSProperties;
              return (
                <g key={ring.id} className="sk-ring-series" data-tone={index % 3} style={style} fill="none">
                  <circle cx="120" cy="121.2" r={radius} stroke="var(--sk-highlight)" strokeWidth={thickness * 1.4} />
                  <circle cx="120" cy="120" r={radius} stroke={`url(#${id}-groove)`} strokeWidth={thickness * 1.3} />
                  <circle cx="120" cy="121.1" r={radius} stroke={`url(#${id}-floor)`} strokeWidth={thickness * .94} />
                  {ring.percent > 0 && (
                    <g className="sk-ring-arc" strokeDasharray={`${ring.percent} 100`} strokeLinecap="round">
                      <circle className="sk-ring-shadow" cx="118.4" cy="120" r={radius} pathLength="100" stroke="var(--sk-arc-shadow)" strokeWidth={thickness} />
                      <circle cx="120" cy="120" r={radius} pathLength="100" stroke="var(--sk-ring-ink)" strokeWidth={thickness} />
                      <circle cx="120" cy="120" r={radius} pathLength="100" stroke={`url(#${id}-bevel)`} strokeWidth={thickness} />
                      <circle cx="120.7" cy="120" r={radius} pathLength="100" stroke={`url(#${id}-fill)`} strokeWidth={thickness * .76} />
                    </g>
                  )}
                  <circle className="sk-ring-target" cx="120" cy="120" r={radius} stroke="transparent" strokeWidth={spacing} onClick={() => setSelectedId(ring.id)} />
                </g>
              );
            })}
          </svg>
          <div className="sk-rings-readout" aria-hidden="true">
            <strong>{formatter.format(selected.percent)}%</strong>
            <span>{selected.label}</span>
          </div>
        </div>
        <ul className="sk-rings-legend" aria-label="Goals">
          {rings.map((ring, index) => (
            <li key={ring.id}>
              <button
                type="button"
                className="sk-ring-series"
                data-tone={index % 3}
                style={{ "--sk-ring-color": ring.color } as CSSProperties}
                aria-pressed={ring.id === selected.id}
                onClick={() => setSelectedId(ring.id)}
              >
                <span className="sk-ring-dot" aria-hidden="true" />
                <span className="sk-ring-label">{ring.label}</span>
                <span className="sk-ring-value">
                  {formatter.format(ring.value)} / {formatter.format(ring.max)}{ring.unit && ` ${ring.unit}`}
                </span>
                <span className="sk-ring-sr">{formatter.format(ring.percent)}% complete</span>
              </button>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

@import "./skeuo-base.css";

.sk-progress-rings {
  width: 100%;
  max-width: 720px;
  margin-inline: auto;
  padding: clamp(16px, 4vw, 30px);
  border: 1px solid var(--sk-edge);
  border-radius: 15px;
  background: linear-gradient(145deg, var(--sk-surface-raised), var(--sk-surface));
  color: var(--sk-card-ink);
  box-shadow: inset 0 2px var(--sk-highlight), 0 4px var(--sk-base),
    0 5px var(--sk-edge), 0 13px 23px var(--sk-shadow);
  container-type: inline-size;
}

.sk-progress-rings > h2 {
  margin: 0 0 12px;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
}

.sk-rings-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  align-items: center;
  gap: clamp(12px, 4vw, 30px);
}

.sk-rings-dial {
  --sk-groove-wall: color-mix(in srgb, var(--sk-base) 68%, black);
  --sk-arc-shadow: color-mix(in srgb, var(--sk-bg) 54%, black);
  position: relative;
  display: grid;
  width: 100%;
  max-width: 270px;
  margin-inline: auto;
  place-items: center;
}

.sk-rings-dial svg {
  display: block;
  width: 100%;
  overflow: visible;
}

.sk-ring-arc {
  transform: rotate(-90deg);
  transform-origin: 120px 120px;
}

.sk-ring-shadow {
  opacity: .52;
  filter: blur(.95px);
}

.sk-ring-target {
  cursor: pointer;
}

.sk-ring-series {
  --sk-ring-ink: var(--sk-ring-color, var(--sk-accent));
}

.sk-ring-series[data-tone="1"] {
  --sk-ring-ink: var(--sk-ring-color, #7f9b8c);
}

.sk-ring-series[data-tone="2"] {
  --sk-ring-ink: var(--sk-ring-color, #a67749);
}

.sk-rings-readout {
  position: absolute;
  display: grid;
  width: 32%;
  justify-items: center;
  gap: 3px;
  text-align: center;
  pointer-events: none;
}

.sk-rings-readout strong {
  font-size: clamp(19px, 7cqi, 36px);
  font-weight: 650;
  line-height: 1;
  letter-spacing: -.04em;
  font-variant-numeric: tabular-nums;
}

.sk-rings-readout span {
  max-width: 100%;
  color: var(--sk-muted);
  font-size: 11px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.sk-rings-legend {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sk-rings-legend button {
  display: grid;
  width: 100%;
  min-height: 44px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 8px 11px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  text-align: left;
  font-size: 13px;
  cursor: pointer;
}

.sk-rings-legend button[aria-pressed="true"],
.sk-rings-legend button:hover {
  border-color: var(--sk-edge);
  background: var(--sk-well);
  box-shadow: inset 0 2px 4px var(--sk-shadow), 0 1px var(--sk-highlight);
}

.sk-rings-legend button:focus-visible {
  outline: 2px solid var(--sk-ring);
  outline-offset: 2px;
}

.sk-ring-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--sk-ring-ink);
  box-shadow: inset 0 1px 1px #ffffff40, 0 1px 2px var(--sk-shadow);
}

.sk-ring-label,
.sk-ring-value {
  overflow-wrap: anywhere;
}

.sk-ring-value {
  max-width: 18ch;
  color: var(--sk-muted);
  text-align: right;
  font: 11px var(--sk-font-mono);
  font-variant-numeric: tabular-nums;
}

.sk-ring-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@container (max-width: 420px) {
  .sk-rings-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .sk-rings-dial[data-animate] .sk-ring-arc {
    animation: sk-ring-sweep 820ms cubic-bezier(.18, .72, .23, 1) var(--sk-ring-delay) backwards;
  }
}

@keyframes sk-ring-sweep {
  from {
    opacity: 0;
    stroke-dasharray: 0 100;
  }

  18% {
    opacity: 1;
  }

  to {
    opacity: 1;
    stroke-dasharray: var(--sk-ring-progress) 100;
  }
}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
